-- Passage rg3-theme-summary-p03
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('0f4c9a89-f31b-5844-b0a7-bef9623cf1ce', 'rg3-theme-summary-p03', (select id from public.skills where slug = 'read-g3-theme-summary'), null,
        '3-5', $q$My Bean Seed$q$, $q$I planted a bean in a paper cup.
I watered it well and I set it up
On the sunny sill by the kitchen door.
I checked it once, then I checked some more.

On Monday, nothing. On Tuesday, the same.
I frowned at the dirt. Was the seed to blame?
On Wednesday I wanted to dig it out.
My grandma said, "Wait. It will sprout."

So I waited through Thursday, and Friday too.
I gave it its water the way I knew.
Then Saturday morning, what did I see?
A little green hook peeking up at me!

Now leaves unfold like a tiny hand.
The stem grows tall, and it starts to stand.
The best things grow when you give them time.
My bean taught me that, in a paper cup of mine.$q$, 'draft')
