values
  ('847845ba-59af-5026-b2ad-72520a539d0f', null, (select id from public.skills where slug = 'read-g3-theme-summary'), null, 'hard',
   $q$Why does the poet list the days of the week, one after another?$q$, $q$[{"text":"To teach readers the names of the days in order.","is_correct":false,"misconception_token":"literal-reading"},{"text":"To show how long the waiting feels, which makes the lesson about patience stronger.","is_correct":true},{"text":"To show that beans only sprout on Saturdays.","is_correct":false,"misconception_token":"overgeneralization"},{"text":"To show that the speaker forgot to water the bean on some days.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$To show how long the waiting feels, which makes the lesson about patience stronger.$q$, $q$Naming Monday through Saturday makes the reader feel the long wait before the sprout, which supports the message about giving things time. The speaker does water it ("I gave it its water"), so forgetting to water is not the reason.$q$, 'draft', '0f4c9a89-f31b-5844-b0a7-bef9623cf1ce')
