  ('2e12670d-2bd7-568f-945f-8c613d8bc134', null, (select id from public.skills where slug = 'read-g3-theme-summary'), null, 'easy',
   $q$What is the moral of this folktale?$q$, $q$[{"text":"Doing a job carefully matters more than doing it fast.","is_correct":true},{"text":"Villages should have a feast every harvest.","is_correct":false,"misconception_token":"detail-not-lesson"},{"text":"The person who works fastest always wins.","is_correct":false,"misconception_token":"contradicts-lesson"},{"text":"Rice should be carried in big bags, not baskets.","is_correct":false,"misconception_token":"literal-reading"}]$q$::jsonb, $q$Doing a job carefully matters more than doing it fast.$q$, $q$Ama's one careful basket holds the rice, while Kofi's quick baskets split. Kofi is faster, but speed does not win in the end.$q$, 'draft', 'a8f00fd1-6a23-50e7-8187-c78e4b01c4f3')
